INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (1, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '
<#macro formatLightCharacterPhase phase multiple=false >
    <#assign flash=multiple?then(''flashes'', ''flash'') >
    <#switch phase>
        <#case "F">fixed light<#break>
        <#case "Fl">${flash}<#break>
        <#case "FFl">fixed light with ${flash}<#break>
        <#case "LFl">long ${flash}<#break>
        <#case "Q">quick ${flash}<#break>
        <#case "VQ">very quick ${flash}<#break>
        <#case "IQ">interrupted quick ${flash}<#break>
        <#case "IVQ">interrupted very quick ${flash}<#break>
        <#case "UQ">ultra quick ${flash}<#break>
        <#case "IUQ">interrupted ultra quick ${flash}<#break>
        <#case "Iso">isophase light<#break>
        <#case "Oc">${multiple?then(''occultings'', ''occulting'')}<#break>
        <#case "Al">alternating<#break>
        <#case "Mo">morse code<#break>
    </#switch>
</#macro>


<#macro formatLightCharacterColor col>
    <#switch col>
        <#case "W">white<#break>
        <#case "G">green<#break>
        <#case "R">red<#break>
        <#case "Y">yellow<#break>
        <#case "B">blue<#break>
        <#case "Am">amber<#break>
    </#switch>
</#macro>


<#macro formatlightGroup lightGroup>
    <#assign multiple=lightGroup.grouped />

    <#if lightGroup.phase == ''Mo''>
        morse code ${lightGroup.morseCode}

    <#elseif lightGroup.phase == ''Al''>
        alternating
        <#if lightGroup.groupSpec?has_content>
            <#list lightGroup.groupSpec as blinks>
                ${blinks} <#if blinks_has_next> + </#if>
            </#list>
        </#if>

        <#if lightGroup.colors?has_content>
            <#list lightGroup.colors as col>
                <#if !col?is_first && col?is_last> and <#elseif !col?is_first>, </#if>
                <@formatLightCharacterColor col=col/>
            </#list>
            flashes
        </#if>

    <#elseif lightGroup.phase == ''Oc''>

        <#if lightGroup.colors?has_content>
            <#list lightGroup.colors as col>
                <#if !col?is_first && col?is_last> and <#elseif !col?is_first>, </#if>
                <@formatLightCharacterColor col=col/>
            </#list> light with
        </#if>

        occulting
        <#if lightGroup.groupSpec?has_content>
            <#list lightGroup.groupSpec as blinks>
            ${blinks} <#if blinks_has_next> + </#if>
            </#list>
        </#if>

    <#else>
        <#if lightGroup.groupSpec?has_content>
            <#list lightGroup.groupSpec as blinks>
                ${blinks} <#if blinks_has_next> + </#if>
            </#list>
        </#if>

        <#if lightGroup.colors?has_content>
            <#list lightGroup.colors as col>
                <#if !col?is_first && col?is_last> and <#elseif !col?is_first>, </#if>
                <@formatLightCharacterColor col=col/>
            </#list>
        </#if>

        <@formatLightCharacterPhase phase=lightGroup.phase multiple=multiple />
    </#if>
</#macro>


<#macro formatlightCharacter lightModel>

    <#if lightModel.lightGroups??>
        <#list lightModel.lightGroups as lightGroup>
            <@formatlightGroup lightGroup=lightGroup /><#if lightGroup_has_next> followed by </#if>
        </#list>

        <#if lightModel.period??>
             <#if lightModel.period == 1>every second<#else>every ${lightModel.period?c} seconds</#if>
        </#if>

        <#if lightModel.elevation??>
            , ${lightModel.elevation?c} <#if lightModel.elevation == 1>meter<#else>meters</#if>
        </#if>

        <#if lightModel.range??>
            , ${lightModel.range?c} <#if lightModel.range == 1>nautical mile<#else>nautical miles</#if>
        </#if>

    </#if>

</#macro>

<@formatlightCharacter lightModel=lightModel/>
', 'templates/aton/light-character.ftl', 'FM');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (2, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '
<#macro formatTelephonyCode code separator="-">
    <#assign result=""/>
    <#list 0..<code?length as i>
        <#if !(i?is_first)>
            <#assign result=result + separator/>
        </#if>
        <#assign result=result + formatTelephonyCharacter(code?substring(i, i+1)?upper_case)/>
    </#list>
    ${result}
</#macro>

<#function formatTelephonyCharacter code>
    <#assign result=""/>
    <#switch code>
        <#case "A"><#assign result="Alpha"/><#break>
        <#case "B"><#assign result="Bravo"/><#break>
        <#case "C"><#assign result="Charlie"/><#break>
        <#case "D"><#assign result="Delta"/><#break>
        <#case "E"><#assign result="Echo"/><#break>
        <#case "F"><#assign result="Foxtrot"/><#break>
        <#case "G"><#assign result="Golf"/><#break>
        <#case "H"><#assign result="Hotel"/><#break>
        <#case "I"><#assign result="India"/><#break>
        <#case "J"><#assign result="Juliet"/><#break>
        <#case "K"><#assign result="Kilo"/><#break>
        <#case "L"><#assign result="Lima"/><#break>
        <#case "M"><#assign result="Mike"/><#break>
        <#case "N"><#assign result="November"/><#break>
        <#case "O"><#assign result="Oscar"/><#break>
        <#case "P"><#assign result="Papa"/><#break>
        <#case "Q"><#assign result="Quebec"/><#break>
        <#case "R"><#assign result="Romeo"/><#break>
        <#case "S"><#assign result="Sierra"/><#break>
        <#case "T"><#assign result="Tango"/><#break>
        <#case "U"><#assign result="Uniform"/><#break>
        <#case "V"><#assign result="Victor"/><#break>
        <#case "W"><#assign result="Whiskey"/><#break>
        <#case "X"><#assign result="Xray"/><#break>
        <#case "Y"><#assign result="Yankee"/><#break>
        <#case "Z"><#assign result="Zulu"/><#break>
        <#case "1"><#assign result="One"/><#break>
        <#case "2"><#assign result="Two"/><#break>
        <#case "3"><#assign result="Three"/><#break>
        <#case "4"><#assign result="Four"/><#break>
        <#case "5"><#assign result="Five"/><#break>
        <#case "6"><#assign result="Six"/><#break>
        <#case "7"><#assign result="Seven"/><#break>
        <#case "8"><#assign result="Eight"/><#break>
        <#case "9"><#assign result="Nine"/><#break>
        <#case "0"><#assign result="Zero"/><#break>
    </#switch>
    <#return result />
</#function>

<@formatTelephonyCode code=code!""/>
', 'templates/aton/telephony-codes.ftl', 'FM');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (3, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '
<#assign formatPos = "org.niord.core.script.directive.LatLonDirective"?new()>
<#assign trailingDot = "org.niord.core.script.directive.TrailingDotDirective"?new()>

<#if geometry?has_content>
    <ul class="positions">
        <#list geometry as feature>
            <#if feature.coordinates?has_content>
                <#list feature.coordinates as coord>
                    <li>
                        <@trailingDot>
                            <@formatPos lat=coord.coordinates[1] lon=coord.coordinates[0] format=format/><#if coord.name?has_content>, ${coord.name}</#if>
                        </@trailingDot>
                    </li>
                </#list>
