INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (13, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '
<#include "../messages/message-support.ftl"/>

<#setting time_zone="GMT+0000">

<#macro renderAreas area lang=language>
    <#if area??>
        <#if area.parent??>
            <@renderAreas area=area.parent lang=lang/>
        </#if>
        <#assign areaDesc=descForLang(area, lang)!>
        <#if areaDesc?? && areaDesc.name?has_content>
            <@trailingDot>${areaDesc.name}</@trailingDot>
        </#if>
    </#if>
</#macro>

<#macro renderNavWarnDetails msg lang=language >

    <#assign msgDesc=descForLang(msg, lang)!>

    <#if msg.publishDateFrom??>
        <div>${msg.publishDateFrom?string[''dd MM yyyy HH:mm'']} UTC</div>
    </#if>

    <#if msg.areas?has_content>
        <div>
            <@renderAreas area=msg.areas[0] lang=lang></@renderAreas>
            <#if msgDesc?? && msgDesc.vicinity?has_content>
                <@trailingDot>${msgDesc.vicinity}</@trailingDot>
            </#if>
        </div>
    </#if>

    <#-- A cancellation warning has no parts: its title names the warning it cancels -->
    <#if msg.kind?? && msg.kind == ''CANCELLATION'' && msgDesc?? && msgDesc.title?has_content>
        <div><@trailingDot>${msgDesc.title}</@trailingDot></div>
    </#if>

    <#if msg.parts?has_content>
        <#list msg.parts as part>
            <#assign partDesc=descForLang(part, lang)!>
            <#if partDesc?? && partDesc.details?has_content>
                <div class="message-details">
                    <@line>${partDesc.details}</@line>
                </div>
            </#if>
        </#list>
    </#if>

</#macro>
', 'templates/mailinglist/publish-navwarn-common.ftl', 'FM');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (14, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '
<#include "publish-navwarn-common.ftl"/>

<html>
<head>
    <link rel="stylesheet" type="text/css" href="/css/templates/mail.css">

    <style>
        .message-details p {
            padding: 0;
            margin: 0;
        }
    </style>
</head>
<body>

    <div>
        Navigational Warning <#if message.shortId?has_content>no. ${message.shortId}</#if>
