INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (23, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '
<#assign line = ''org.niord.core.script.directive.LineDirective''?new()>
<#assign formatPos = "org.niord.core.script.directive.LatLonDirective"?new()>
<#assign formatDateInterval = "org.niord.core.script.directive.DateIntervalDirective"?new()>
<#assign txtToHtml = "org.niord.core.script.directive.TextToHtmlDirective"?new()>
<#assign trailingDot = "org.niord.core.script.directive.TrailingDotDirective"?new()>

<#-- ***************************************  -->
<#-- Parametrized message styles             -->
<#-- ***************************************  -->
<#macro pageSizeStyle frontPage=true>
    <style type="text/css" media="all">

        @page {
            size: ${pageSize!"A4"} ${pageOrientation!"portrait"};
        }

    <#if frontPage>
        /** First page rules **/
        @page :first {
            margin: 1.5cm 1.0cm;
            @top-center {
                content: element(first-page-header);
            }
            @bottom-center {
                content: element(first-page-footer);
            }
        }
    </#if>

    </style>
</#macro>


<#-- ***************************************  -->
<#-- Renders the default headers and footers  -->
<#-- ***************************************  -->
<#macro renderDefaultHeaderAndFooter headerText frontPage=true>
    <#if frontPage>
        <div class="first-page-header">
        </div>
    </#if>
    <div class="header">
        <span style="float: left">${headerText}</span>
        <span style="float: right">${text("pdf.page")} <span id="pagenumber"></span></span>
        &nbsp;
    </div>

    <#include "message-list-pdf-footer.ftl">
</#macro>


<#-- ***************************************  -->
<#-- Renders the parent-first area lineage    -->
<#-- ***************************************  -->
<#macro areaLineage area>
    <#if area??>
        <#if area.parent??>
            <@areaLineage area=area.parent /> -
        </#if>
        <#if area.descs?has_content>${area.descs[0].name}</#if>
    </#if>
</#macro>


<#-- ***************************************  -->
<#-- Returns the two root-most area headings  -->
<#-- ***************************************  -->
<#function areaHeading area="area" >
    <#if area?? && (!area.parent?? || (area.parent?? && !area.parent.parent??))>
        <#return area/>
    </#if>
    <#if area?? >
        <#return areaHeading(area.parent) />
    </#if>
    <#return NULL/>
</#function>


<#-- ***************************************  -->
<#-- Returns if the attachment has the given type  -->
<#-- ***************************************  -->
<#function includeAttachment att type >
    <#return att.display?has_content && att.display == type && att.type?has_content && att.type?starts_with(''image'')/>
</#function>


<#-- ***************************************  -->
<#-- A repository path as an address: each segment encoded, the slashes kept.
     A path is stored encoded (an upload''s) or as the file was named (an imported
     message''s). A segment that reads as encoded, every "%" in it starting the
     escapes of a UTF-8 character, keeps its escapes (%25, %3B, %20, %C3%98) and
     has every other character encoded; any other segment is a name as it was
     uploaded and is encoded whole, its "%" signs included. So both spellings
     give the same address. The admin app and the public site encode a path by
     the same rule (encodeRepoPath, which decodes a segment where it decodes). -->
<#-- ***************************************  -->
<#function repoPathUrl path>
    <#-- The escapes of one UTF-8 byte that continues a character (80-BF) -->
    <#local cont = ''%[89ab][0-9a-f]'' />
    <#-- One character of a segment that reads as encoded: anything but "%", or the escapes of one
         UTF-8 character, which leaves out an overlong form and a surrogate, as a decoder does -->
    <#local encodedChar = ''[^%]|%[0-7][0-9a-f]|%(?:c[2-9a-f]|d[0-9a-f])'' + cont
        + ''|%e0%[ab][0-9a-f]'' + cont + ''|%e[1-9a-cef]'' + cont + cont + ''|%ed%[89][0-9a-f]'' + cont
        + ''|%f0%[9ab][0-9a-f]'' + cont + cont + ''|%f[1-3]'' + cont + cont + cont + ''|%f4%8[0-9a-f]'' + cont + cont />
    <#local out = '''' />
    <#list path?split(''/'') as segment>
        <#if !segment?is_first><#local out = out + ''/'' /></#if>
        <#if segment?matches(''(?:'' + encodedChar + '')*'', ''i'')>
            <#list segment?matches(r''%[0-9A-Fa-f]{2}|[^%]+'') as part>
                <#local out = out + part?starts_with(''%'')?then(part, part?url(''UTF-8'')) />
            </#list>
        <#else>
            <#local out = out + segment?url(''UTF-8'') />
        </#if>
    </#list>
    <#return out />
</#function>


<#-- ***************************************  -->
<#-- Renders an attachment  -->
<#-- ***************************************  -->
<#macro renderAttachment att >
    <#assign imageStyle=''max-width: 100%;'' />
    <#if att.width?has_content && att.height?has_content>
        <#assign imageStyle="max-width: 100%; width: " + att.width + "; height: " + att.height />
    <#elseif att.width?has_content>
        <#assign imageStyle="max-width: 100%; width: " + att.width + "; " />
    <#elseif att.height?has_content>
        <#assign imageStyle="max-width: 100%; height: " + att.height + "; " />
    </#if>

    <div class="attachment">
        <div>
            <img src="/rest/repo/file/${repoPathUrl(att.path)}" style="${imageStyle}">
        </div>
        <#if att.descs?has_content && att.descs[0].caption?has_content>
            <div style="margin: 1mm; font-style: italic">${att.descs[0].caption}</div>
        </#if>
    </div>
</#macro>


<#-- ***************************************  -->
<#-- Renders all nessage attachments of the given type    -->
<#-- ***************************************  -->
<#macro renderMessageAttachments msg type>
    <#if msg.attachments?has_content>
        <#list msg.attachments as att>
            <#if includeAttachment(att, type)>
                <@renderAttachment att=att />
            </#if>
        </#list>
    </#if>
</#macro>


<#-- ***************************************  -->
<#-- Renders all separate-page attachments    -->
<#-- ***************************************  -->
<#macro renderSeparatePageAttachments msg>
    <#if msg.attachments?has_content>
        <#list msg.attachments as att>
            <#if includeAttachment(att, ''SEPARATE_PAGE'')>
            <div class="separate-attachment-page">
                <#assign messageId=msg.id />
                <#if msg.shortId?has_content>
                    <#assign messageId=msg.shortId />
                </#if>
                <div style="margin: 1mm">
                    <h4 id="${messageId}">${text("msg.attachment.title", messageId)}</h4>
                </div>
                <@renderAttachment att=att />
            </div>
            </#if>
        </#list>
    </#if>
</#macro>


<#-- ***************************************  -->
<#-- Renders the TOC for area-headings        -->
<#-- ***************************************  -->
<#macro renderTOC messages areaHeadings prefix="">
    <#if areaHeadings>
        <div>
            <h2>${text("pdf.toc")}</h2>
            <@renderTOCEntries messages=messages prefix=prefix />
        </div>
    </#if>
</#macro>


<#macro renderTOCEntries messages prefix="">
    <#assign tocAreaHeadingId=-9999999 />
    <ol class=''toc''>
        <#list messages as msg>
            <#if msg.areas?has_content>
                <#assign area=areaHeading(msg.areas[0]) />
                <#if area?? && area.id != tocAreaHeadingId>
                    <#assign tocAreaHeadingId=area.id />
                    <li><a href=''#${prefix}${tocAreaHeadingId?c}''><@areaLineage area=areaHeading(area) /></a></li>
                </#if>
            <#elseif  tocAreaHeadingId == -9999999>
                <li><a href=''#${prefix}${tocAreaHeadingId?c}''>${text("msg.area.general")}</a></li>
                <#assign tocAreaHeadingId=-9999998 />
            </#if>
        </#list>
    </ol>
</#macro>


<#-- ***************************************  -->
<#-- Returns the desc for the given language  -->
<#-- ***************************************  -->
<#function descForLang entity lang=language >
    <#if entity.descs?has_content>
        <#list entity.descs as desc>
            <#if desc.lang?? && desc.lang == lang>
                <#return desc />
            </#if>
        </#list>
    </#if>
    <#if entity.descs?has_content>
        <#return entity.descs[0] />
    </#if>
</#function>


<#-- ***************************************  -->
<#-- Returns the given promulgation           -->
<#-- ***************************************  -->
<#function promulgation msg type >
    <#if msg.promulgations?has_content>
        <#list msg.promulgations as p>
            <#if p.type?? && p.type.typeId == type>
                <#return p />
            </#if>
        </#list>
    </#if>
</#function>


<#-- ***************************************  -->
<#-- Renders a language flag if wrong lang    -->
<#-- ***************************************  -->
<#macro renderLangFlag desc lang=language  draft=draft!false >
    <#if draft == true && desc?? && desc.lang != lang>
        <img src="/img/flags/${desc.lang}.png" class="lang-flag"/>
    </#if>
</#macro>


<#-- ***************************************  -->
<#-- Renders the number and year of a         -->
<#-- as "number-3-digits/year-2-digits"       -->
<#-- ***************************************  -->
<#macro renderNumberYearId message defaultValue="" >
    <#if message?? && message.year?? && message.number??>
        ${message.number?string[''000'']}/${(message.year % 100)?string[''00'']}
    <#else>
        ${defaultValue}
    </#if>
</#macro>


<#-- ***************************************  -->
<#-- Renders the message source + publ. date  -->
<#-- ***************************************  -->
<#function renderSource desc msg >
    <#assign source=""/>
    <#if desc?? && desc.source?has_content>
        <#assign source=source + desc.source/>
    </#if>
    <#if desc?? && desc.source?has_content && msg.publishDateFrom??>
        <#assign source=source?remove_ending(".") + ". "/>
    </#if>
    <#if msg.publishDateFrom??>
        <#assign source=source + text(''msg.field.published'') + '' '' + msg.publishDateFrom?string(text(''msg.time.date_format''))/>
    </#if>
    <#return source/>
</#function>


<#-- ***************************************  -->
<#-- Renders a message part                   -->
<#-- ***************************************  -->
<#macro renderMessagePart part lang=language draft=draft!false >
    <#assign partDesc=descForLang(part, lang)!>
    <#if !(part.hideSubject!false) && partDesc?? && partDesc.subject??>
        <p>
            <strong>${partDesc.subject}</strong>
            <@renderLangFlag desc=partDesc lang=lang draft=draft/>
        </p>
    </#if>
    <#if partDesc?? && partDesc.details??>
        <div>
            <@line>${partDesc.details}</@line>
        </div>
    </#if>
</#macro>


<#-- ***************************************  -->
<#-- Renders a message                        -->
<#-- ***************************************  -->
<#macro renderMessage msg lang=language draft=draft!false link=link!false >

    <#assign msgDesc=descForLang(msg, lang)!>

    <div style="width: 100%;">

    <#-- Attachments to display above message -->
    <@renderMessageAttachments msg=msg type="ABOVE" />


    <#-- Title line -->
    <#if msg.originalInformation?has_content && msg.originalInformation>
        <div class="avoid-break-after original-information">*</div>
    </#if>

    <#if msg.shortId?has_content>
        <div class="avoid-break-before-after">
            <span class="label-message-id">${msg.shortId}</span>
            <#if msg.status == ''CANCELLED'' || (msg.status == ''EXPIRED'' && msg.type != ''PERMANENT_NOTICE'')>
                <span class="label-status">${text("msg.status." + msg.status)}</span>
            </#if>
            <#if msg.mainType == ''NM'' && msg.type??>
                <#switch msg.type>
                    <#case ''TEMPORARY_NOTICE''>(T)<#break>
                    <#case ''PRELIMINARY_NOTICE''>(P)<#break>
                </#switch>
            </#if>
        </div>
    </#if>

    <#if msgDesc?has_content && msgDesc.title?has_content>
        <div class="avoid-break-before-after" id="msg_${msg.id}">
            <strong>
                <#if link == true>
                    <a href="${adminAppUrl}/messages?messageId=${msg.id?url(''UTF-8'')}" target="_blank" id="msg_${msg.id}">
                        ${msgDesc.title}
                    </a>
                <#else>
                    ${msgDesc.title}
                </#if>
            </strong>
            <@renderLangFlag desc=msgDesc lang=lang />
        </div>
    </#if>


    <table class="field-table">

        <#-- Type line (drafts only) -->
        <#if draft == true>
            <tr>
                <td class="field-name">${text("msg.field.type")}</td>
                <td class="field-value">
                    ${text("msg.type." + msg.type)} ${msg.mainType}
                </td>
            </tr>
        </#if>

        <#-- Status (drafts only) -->
        <#if draft == true>
            <tr>
                <td class="field-name">${text("msg.field.status")}</td>
                <td class="field-value">
                    ${msg.status?lower_case}
                </td>
            </tr>
        </#if>

        <#-- Reference lines -->
        <#if msg.references?has_content>
            <tr>
                <td class="field-name">
                    ${text("msg.field.references")}
                </td>
                <td class="field-value">
                    <#list msg.references as ref>
                        <#assign refDesc=descForLang(ref, lang)!>
                        <div>
                            <@trailingDot>
                                <#if link == true>
                                    <a href="${adminAppUrl}/messages?messageId=${ref.messageId?url(''UTF-8'')}" target="_blank" id="msg_${ref.messageId}">
                                        ${ref.messageId}
                                    </a>
                                <#else>
                                    ${ref.messageId}
                                </#if>

                                <#if ref.type == ''REPETITION''>
                                    - ${text("msg.reference.repetition")}
                                <#elseif ref.type == ''REPETITION_NEW_TIME''>
                                    - ${text("msg.reference.repetition_new_time")}
                                <#elseif ref.type == ''CANCELLATION''>
                                    - ${text("msg.reference.cancellation")}
                                <#elseif ref.type == ''UPDATE''>
                                    - ${text("msg.reference.update")}
                                </#if>

                                <#if refDesc?has_content && refDesc.description??>
                                    - ${refDesc.description}
                                </#if>
                            </@trailingDot>
                        </div>
                    </#list>
                </td>
            </tr>
        </#if>


        <#-- Details line -->
        <#if msg.parts?has_content>
            <#list msg.parts as part>
                <tr style="page-break-inside: auto;">
                    <td class="field-name">
                        <#if part?is_first || part.type != msg.parts[part?index - 1].type>
                            ${text("msg.field." + part.type?lower_case)}
                        </#if>
                    </td>
                    <td class="field-value message-description" style="page-break-inside: auto;">
                        <@renderMessagePart part=part lang=lang draft=draft/>
                    </td>
                </tr>
            </#list>
        </#if>


        <#-- Charts line -->
        <#if msg.charts?has_content>
            <tr>
                <td class="field-name">${text("msg.field.charts")}</td>
                <td class="field-value">
                    <@trailingDot>
                        <#list msg.charts as chart>
                          ${chart.chartNumber}<#if chart.internationalNumber?has_content> (INT ${chart.internationalNumber?c})</#if><#if chart_has_next>,</#if>
                        </#list>
                    </@trailingDot>
                </td>
            </tr>
        </#if>

        <#-- Publication line -->
        <#if msgDesc?has_content && msgDesc.publication?has_content>
            <tr>
                <td class="field-name">${text("msg.field.publication")}</td>
                <td class="field-value">
                ${msgDesc.publication!""}
                </td>
            </tr>
        </#if>

        <#-- Source line -->
        <#assign source=renderSource(msgDesc, msg)/>
        <#if source?has_content>
            <tr>
                <td class="field-value" align="right" colspan="2">
                    (${source!""})
                </td>
            </tr>
        </#if>

    </table>

    <#-- Attachments to display below message -->
    <@renderMessageAttachments msg=msg type="BELOW" />

    </div>

</#macro>


<#-- ***************************************  -->
<#-- Renders a list of messages               -->
<#-- ***************************************  -->
<#macro renderMessageList messages areaHeadings=true prefix="" draft=draft!false link=link!false>

    <#assign areaHeadingId=-9999999 />

    <table class="message-table">
        <#-- Layout row for fixed-layout table -->
        <tr>
            <#if mapThumbnails!true>
                <#assign colspan=2 />
                <td width="140"></td>
                <td width="*"></td>
            <#else>
                <#assign colspan=1 />
                <td width="100%"></td>
            </#if>
        </tr>

        <#list messages as msg>

            <#if msg.areas?has_content>
                <#assign area=areaHeading(msg.areas[0]) />
                <#if areaHeadings && area?? && area.id != areaHeadingId>
                    <#assign areaHeadingId=area.id />
                    <tr class="table-header-row">
                        <td colspan="${colspan}" class="table-header"><h4 id="${prefix}${areaHeadingId?c}"><@areaLineage area=areaHeading(area) /></h4></td>
                    </tr>
                </#if>
            <#elseif  areaHeadings && areaHeadingId == -9999999>
                <tr class="table-header-row">
                    <td colspan="${colspan}" class="table-header"><h4 id="${prefix}${areaHeadingId?c}">${text("msg.area.general")}</h4></td>
                </tr>
                <#assign areaHeadingId=-9999998 />
            </#if>
            <#if separatePageIds?? && separatePageIds?seq_contains(msg.id)>
                <#assign msgClass="break-before" />
            <#else>
                <#assign msgClass="" />
            </#if>
            <tr class="${msgClass}">
                <#if mapThumbnails!true>
                    <td class="table-image">
                        <img src="/rest/message-map-image/${msg.id}.png" width="120" height="120"/>
                    </td>
                </#if>
                <td class="table-item">
                    <#if draft>
                        <#list languages as lang>
                            <#if lang?is_first>
                                <#-- A language no dictionary names (no lang.<code>) is named by its code, as the administration app does -->
                                <div class="lang-header-first">
                                    <img src="/img/flags/${lang}.png" height="12"/>&nbsp;<#attempt>${text(''lang.'' + lang)}<#recover>${lang?upper_case}</#attempt> ${text(''pdf.translation'')}
                                </div>
                            <#else>
                                <div class="lang-header">
                                    <img src="/img/flags/${lang}.png" height="12"/>&nbsp;<#attempt>${text(''lang.'' + lang)}<#recover>${lang?upper_case}</#attempt> ${text(''pdf.translation'')}
                                </div>
                            </#if>
                            <@renderMessage msg=msg lang=lang draft=draft link=link/>
                        </#list>
                    <#else>
                        <@renderMessage msg=msg lang=language draft=draft link=link/>
                    </#if>
                </td>
            </tr>
        </#list>
    </table>

    <#list messages as msg>
        <@renderSeparatePageAttachments msg=msg />
    </#list>

</#macro>
', 'templates/messages/message-support.ftl', 'FM');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (24, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '<#-- introduction: this deployment''s text goes here -->
', 'templates/messages/nm-accumulated-report-pdf-intro.ftl', 'FM');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (25, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '<#include "message-support.ftl"/>

<#--
    The accumulated notices: a year drawn as the weeks it was compiled from.

    The document is sectioned rather than flat, and the sections arrive in the
    model as "groups" -- each one a source issue, its numbers, its content period and the
    ids of the messages it printed, in the order that issue printed them. The ids
    partition the ordered "messages" list rather than duplicating it, so a section
    can never print something the list does not contain.

    A section whose id list is empty is a week that printed nothing, and it is
    still listed and still printed -- with its heading and one sentence in place
    of the tables. The sections are the record of what the year covered, and a
    year that quietly prints fifty-one of its fifty-two weeks is a document
    claiming a week was never covered.

    A model with no groups still renders: the flat list under one heading. That is
    what a preview of an unsourced issue, or any other report pointed at this
    template, produces.
-->

<#-- A cut-off is an instant, and which DAY it falls on is answered by the zone the
     publication''s own desk keeps -- never by the renderer''s, which on an unattended
     release is whatever zone the container happens to run in. -->

<#if timeZone?has_content>
    <#setting time_zone=timeZone>
</#if>

<#--
    The messages of one section.

    A section that was handed its own members uses them. A section that was only
    named its ids picks them out of the ordered list, which is what a model built
    by hand -- the report editor, a fixture -- hands over, and costs one scan of
    the whole list per section.
-->
<#function messagesOfGroup group>
    <#if group.messages??>
        <#return group.messages />
    </#if>
    <#return messages?filter(msg -> group.messageIds?seq_contains(msg.id)) />
</#function>

<#-- The first and last printed number of a set of messages, where they have any. -->
<#macro numberRange msgs>
    <#local minNo = -1 />
    <#local maxNo = -1 />
    <#list msgs as msg>
        <#if msg.number??>
            <#if minNo == -1 || msg.number lt minNo><#local minNo = msg.number /></#if>
            <#if maxNo == -1 || msg.number gt maxNo><#local maxNo = msg.number /></#if>
        </#if>
    </#list>
    <#if minNo != -1>${minNo?c} - ${maxNo?c}</#if>
</#macro>

<#-- What a section is called: the source issue''s own name, or what it is instead. -->
<#macro groupTitle group>
    <#compress>
        <#if group.manual>
            ${text(''pdf.accumulated.added_by_hand'')}
        <#elseif group.name?has_content>
            ${group.name}
        <#elseif group.week??>
            ${text(''pdf.week'')} ${group.weeks!(group.week?c)}
        <#else>
            ${text(''pdf.nm'')}
        </#if>
    </#compress>
</#macro>

<#--
    One section''s messages, split the way the weekly splits its own: the notices
    proper with area headings, then the announcements under their own heading.

    Split by ?filter rather than by appending to a list one message at a time.
    Appending builds a sequence out of a chain of concatenations, one link per
    message, and reading the n''th element walks the chain -- so printing the list
    afterwards costs the square of its length. On a section of twenty that is
    nothing; on the flat list a one-off or an unsourced preview produces, where
    the whole document is one "section" of three thousand, it was the largest
    single term in the time to render.
-->
<#macro renderGroupBody msgs prefix>
    <#local nmMsgs = msgs?filter(msg -> msg.type != ''MISCELLANEOUS_NOTICE'') />
    <#local miscMsgs = msgs?filter(msg -> msg.type == ''MISCELLANEOUS_NOTICE'') />

    <#if nmMsgs?has_content>
        <@renderMessageList messages=nmMsgs areaHeadings=areaHeadings prefix=prefix/>
    </#if>

    <#if miscMsgs?has_content>
        <table width="100%">
            <tr>
                <td class="table-header"><h4 id="${prefix}misc">${text(''pdf.misc_nm'')}</h4></td>
            </tr>
        </table>
        <@renderMessageList messages=miscMsgs areaHeadings=false prefix="${prefix}misc"/>
    </#if>
</#macro>


<html>
<head>

    <meta http-equiv="Content-Type" content="text/html; charset=UTF-8"/>
    <title>${text("pdf.accumulated.title")}</title>

    <@pageSizeStyle />
    <link rel="stylesheet" type="text/css" href="/css/templates/pdf.css">
    <link rel="stylesheet" type="text/css" href="/css/templates/common.css">

    <style type="text/css" media="all">
        .nm-toc {
            margin-top: 1cm;
        }
        .toc {
            font-size: 12px;
        }
        .intro {
            margin-top: 2cm;
            font-size: 12px;
            page-break-after:always;
        }
        .intro table {
            margin: 0 auto;
            font-size: 12px;
            text-align: left;
        }
        .intro table th {
            width: 2cm;
            font-weight: normal;
        }
        .year-header {
            font-size: 24px;
            text-align: right;
            margin-top: 1cm;
            margin-bottom: 1mm;
        }
        .group-header {
            margin-top: 8mm;
            page-break-after: avoid;
        }
        .group-header h3 {
            margin-bottom: 1mm;
        }
        .group-info-line {
            font-size: 11px;
            border-bottom: 1px solid #999999;
            padding-bottom: 1mm;
        }
        /* The sentence a section with nothing in it carries: the intro''s text
           size, and none of its cover-page spacing or page break. */
        .group-empty {
            font-size: 12px;
            margin-top: 4mm;
        }
    </style>

</head>
<body>

<#-- Headers and footers -->
<@renderDefaultHeaderAndFooter headerText="${text(''pdf.accumulated.title'')} ${year!''''}"/>


<#--
    First page. ${year} is the year LABEL and prints exactly as it was typed:
    free text, in letters as readily as in digits. The volume is counted from
    ${yearNumber}, the year the numbering derived -- never from the label, which
    is not arithmetic to do, and never from the clock, which would stamp the year
    of printing on a document of a year that has been over for months. An issue
    whose numbering derived no year prints no volume line at all.
-->
<h1>${text("pdf.accumulated.title")}</h1>

<div class="year-header">
    ${year!""}
</div>
<table class="first-page-info-line">
    <tr>
        <#-- The weekly prints the day it was made here. This one cannot: an annual
             is routinely rendered again years later, and a printing date would be
             the only part of the document that was not about its own year. -->
        <td width="25%" align="left">
            <#if edition?? && edition != ''1''>Version ${edition}</#if>
        </td>
        <td width="25%" align="center">ISSN ${ISSN!""}</td>
        <td width="25%" align="center">
            <#if yearNumber??>${text(''pdf.volume'', (yearNumber - 1884))}</#if>
        </td>
        <td width="25%" align="right"><@numberRange msgs=messages /></td>
    </tr>
</table>

<#if groups?has_content>
    <div class="nm-toc">
        <h2>${text("pdf.toc")}</h2>
        <ol class=''toc''>
            <#list groups as group>
                <#-- Every section, the empty ones included: the contents list what
                     the year covered, and a week missing from it reads as a week
                     that was never covered at all. -->
                <li><a href=''#group_${group?index}''><@groupTitle group=group /></a></li>
            </#list>
        </ol>
    </div>
</#if>


<div class="intro">
    <#include "nm-accumulated-report-pdf-intro.ftl">
</div>


<#if groups?has_content>

    <#list groups as group>
        <#assign groupMessages = messagesOfGroup(group) />

        <#-- EVERY section is printed, including one nothing was filed under. The
             sections are the record of what the year covered, so a week that
             printed nothing still gets its heading and says so in a sentence; a
             year that quietly prints fifty-one of its fifty-two weeks is a
             document claiming a week was never covered. -->

        <#if !group?is_first>
            <div class="page-break"></div>
        </#if>

        <div class="group-header">
            <h3 id="group_${group?index}"><@groupTitle group=group /></h3>
            <table class="group-info-line" width="100%">
                <tr>
                    <td width="40%" align="left">
                        <#-- group.weeks is the source''s weeks in the pair form the name patterns
                             use: "36+37" for a pair, "36-38" for three weeks or more. -->
                        <#if !group.manual && group.week??>
                            ${text(''pdf.week'')} ${group.weeks!(group.week?c)}<#if group.year??>, ${group.year?c}</#if>
                        </#if>
                    </td>
                    <td width="30%" align="center">
                        <#-- The stretch the week''s notices were published in, which is what a
                             reader of the year looks a week up by. A source with no period
                             start -- an in-force edition is a single instant -- has its
                             cut-off alone. ?datetime because a Date arrives without a
                             declared kind. -->
                        <#if group.cutoff?? && group.intervalFrom??>
                            ${text(''pdf.accumulated.period'')}: ${group.intervalFrom?datetime?string(text("msg.time.date_format"))} - ${group.cutoff?datetime?string(text("msg.time.date_format"))}
                        <#elseif group.cutoff??>
                            ${text(''pdf.accumulated.cutoff'')}: ${group.cutoff?datetime?string(text("msg.time.date_format"))}
                        </#if>
                    </td>
                    <#-- No range where there are no numbers to range over. -->
                    <td width="30%" align="right"><#if groupMessages?has_content><@numberRange msgs=groupMessages /></#if></td>
                </tr>
            </table>
        </div>

        <#if groupMessages?has_content>
            <@renderGroupBody msgs=groupMessages prefix="g${group?index}"/>
        <#else>
            <p class="group-empty">${text(''pdf.accumulated.no_messages'')}</p>
        </#if>
    </#list>

<#elseif messages?has_content>

    <#-- No sections: the ordered list, whole, exactly as the weekly prints one. -->
    <div class="group-header">
        <h3>${text(''pdf.nm'')}</h3>
    </div>
    <@renderGroupBody msgs=messages prefix="nm"/>

</#if>

</body>
</html>
', 'templates/messages/nm-accumulated-report-pdf.ftl', 'FM');
