', 'templates/messages/nm-almanac-report-pdf-intro.ftl', 'FM');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (27, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '<#include "message-support.ftl"/>

<html>
<head>

    <meta http-equiv="Content-Type" content="text/html; charset=UTF-8"/>
    <title>${text("pdf.list.title")}</title>

    <@pageSizeStyle />
    <link rel="stylesheet" type="text/css" href="/css/templates/pdf.css">
    <link rel="stylesheet" type="text/css" href="/css/templates/common.css">

    <style type="text/css" media="all">
        table.contact-info {
            margin-bottom: 5mm;
            font-size: 11px;
        }
        table.contact-info tr td {
            padding: 3mm;
        }
    </style>

</head>
<body>

<@renderDefaultHeaderAndFooter headerText="${text(''pdf.nm_almanac.title'')} - ${text(''pdf.nm_almanac.subtitle'')}"/>

<h1 style="margin-top: 5mm">${text("pdf.nm_almanac.title")}</h1>

<h5>${text("pdf.nm_almanac.desc")}</h5>

<table class="first-page-info-line" style="margin-top: 5mm">
    <tr>
        <td>
            ${.now?string(text(''msg.time.date_format''))}
            <#if edition?? && edition != ''1''> - Version ${edition}</#if>
        </td>
        <td align="right">${text("pdf.nm_almanac.subtitle")}</td>
    </tr>
</table>

<div>
  <#include "nm-almanac-report-pdf-intro.ftl">
</div>

<div>
    <h2>${text("pdf.toc")}</h2>
    <table width="100%" cellpadding="1" cellspacing="0">
        <#list messages as msg>
            <#if msg.descs?has_content && msg.descs[0].title?has_content>
                <tr>
                    <td style="width: 2cm" valign="top">
                        <a href=''#msg_${msg.id}''><#if msg.shortId?has_content>${msg.shortId}</#if></a>
                    </td>
                    <td width="*">
                        <div class="toc"><a href=''#msg_${msg.id}''>${msg.descs[0].title}</a></div>
                    </td>
                </tr>
            </#if>
        </#list>
    </table>
</div>


<div class="page-break">&nbsp;</div>

<@renderMessageList messages=messages areaHeadings=areaHeadings/>

</body>
</html>
', 'templates/messages/nm-almanac-report-pdf.ftl', 'FM');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (28, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '<#include "message-support.ftl"/>

<html>
<head>

    <meta http-equiv="Content-Type" content="text/html; charset=UTF-8"/>
    <title>${text("pdf.list.title")}</title>

    <@pageSizeStyle frontPage=true/>
    <link rel="stylesheet" type="text/css" href="/css/templates/pdf.css">
    <link rel="stylesheet" type="text/css" href="/css/templates/common.css">

</head>
<body>


<#assign msg=messages[0] />

<#-- Construct the title -->
<#assign title="" />
<#if msg.descs?has_content && msg.descs[0].title?has_content>
    <#assign title=msg.descs[0].title />
</#if>
<#if msg.parts?has_content>
    <#list msg.parts as part>
        <#if part.type == ''DETAILS'' && part.descs?has_content && part.descs[0].subject?has_content>
            <#assign title=part.descs[0].subject />
        </#if>
    </#list>
</#if>
<#assign title=title?remove_ending(".") />

<@renderDefaultHeaderAndFooter headerText="${text(''pdf.nm_annex.nm_ref'', .vars[''NtM-ref'']!'''')}" frontPage=true/>

<h1 style="margin-top: 5mm">${title}</h1>

<table class="first-page-info-line" style="margin: 1cm 0">
    <tr>
        <td>
            ${.now?string(text(''msg.time.date_format''))}
            <#if edition?? && edition != ''1''> - Version ${edition}</#if>
        </td>
        <td align="right">
            ${text("pdf.nm_annex.nm_ref", .vars[''NtM-ref'']!"")}
        </td>
    </tr>
</table>

<@renderMessageList messages=messages areaHeadings=false/>

</body>
</html>
', 'templates/messages/nm-annex-report-pdf.ftl', 'FM');
