', 'templates/messages/nm-report-pdf-intro.ftl', 'FM');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (30, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '<#include "message-support.ftl"/>

<#--
    Split by ?filter rather than by appending to a list one message at a time.
    Appending builds a sequence out of a chain of concatenations, one link per
    message, and reading the n''th element walks the chain -- so printing the list
    afterwards costs the square of its length.
-->
<#assign nmMessages = messages?filter(msg -> msg.type != ''MISCELLANEOUS_NOTICE'') />
<#assign miscMessages = messages?filter(msg -> msg.type == ''MISCELLANEOUS_NOTICE'') />
<#assign minMessageNo = 9999999 />
<#assign maxMessageNo = -9999999 />
<#list messages as msg>
    <#if msg.number?? && msg.number lt minMessageNo >
        <#assign minMessageNo = msg.number />
    </#if>
    <#if msg.number?? && msg.number gt maxMessageNo >
        <#assign maxMessageNo = msg.number />
    </#if>
</#list>


<html>
<head>

    <meta http-equiv="Content-Type" content="text/html; charset=UTF-8"/>
    <title>${text("pdf.list.title")}</title>

    <@pageSizeStyle />
    <link rel="stylesheet" type="text/css" href="/css/templates/pdf.css">
    <link rel="stylesheet" type="text/css" href="/css/templates/common.css">

    <style type="text/css" media="all">
        .nm-toc {
            margin-top: 1cm;
        }
        .toc {
            font-size: 12px;
        }
        .intro {
            margin-top: 2cm;
            font-size: 12px;
            page-break-after:always;
        }
        .intro table {
            margin: 0 auto;
            font-size: 12px;
            text-align: left;
        }
        .intro table th {
            width: 2cm;
            font-weight: normal;
        }
        .week-year-header {
            font-size: 24px;
            text-align: right;
            margin-top: 1cm;
            margin-bottom: 1mm;
        }
    </style>

</head>
<body>

<#-- Headers and footers. ${weeks} is the issue''s weeks in the pair form the name
     patterns use: "36", "36+37" for a pair, "36-38" for three weeks or more, or
     the week label whole. The legacy print dialog hands only ${week}, which then
     prints alone. -->
<@renderDefaultHeaderAndFooter headerText="${text(''pdf.nm'')} - ${text(''pdf.week'')} ${weeks!week!''''}, ${year!''''}"/>


<#-- First page -->
<h1>${text("pdf.nm")}</h1>

<div class="week-year-header">
    ${text("pdf.week")} ${weeks!week!""}, ${year!""}
</div>
<table class="first-page-info-line">
    <tr>
        <td width="25%" align="left">
            ${.now?string(text("msg.time.date_format"))}
            <#if edition?? && edition != ''1''> - Version ${edition}</#if>
        </td>
        <td width="25%" align="center">ISSN ${ISSN!""}</td>
        <#-- The volume is counted from ${yearNumber}, the year the numbering
             derived, and not from the clock: a December issue amended in January,
             and any re-render years later, would otherwise print the volume of the
             year it was printed in rather than of the year it is the issue for.
             The legacy print dialog renders this same template with no issue
             behind it, so where no year was derived the clock still answers. -->
        <td width="25%" align="center"><#if yearNumber??>${text(''pdf.volume'', (yearNumber - 1884))}<#else>${text(''pdf.volume'', (.now?string(''yyyy'')?number - 1884))}</#if></td>
        <td width="25%" align="right">
            <#if minMessageNo != 9999999 && maxMessageNo != -9999999>
                ${minMessageNo?c} - ${maxMessageNo?c}
            </#if>
        </td>
    </tr>
</table>

<div class="nm-toc">
    <h2>${text("pdf.toc")}</h2>
    <ol class=''toc''>

        <#assign tocAreaHeadingId=-9999999 />
        <#list nmMessages as msg>
            <#if msg.areas?has_content>
                <#assign area=areaHeading(msg.areas[0]) />
                <#if area?? && area.id != tocAreaHeadingId>
                    <#assign tocAreaHeadingId=area.id />
                    <li><a href=''#nm${tocAreaHeadingId?c}''><@areaLineage area=areaHeading(area) /></a></li>
                </#if>
            <#elseif  tocAreaHeadingId == -9999999>
                <li><a href=''#nm${tocAreaHeadingId?c}''>${text("msg.area.general")}</a></li>
                <#assign tocAreaHeadingId=-9999998 />
            </#if>
        </#list>

        <#if miscMessages?has_content>
            <li>
                <div class="toc"><a href=''#misc''>${text(''pdf.misc_nm'')}</a></div>
            </li>
        </#if>
    </ol>
</div>


<div class="intro">
    <#include "nm-report-pdf-intro.ftl">
</div>


<#-- Permanent and T&P messages -->
<#if nmMessages?has_content>
    <@renderMessageList messages=nmMessages areaHeadings=areaHeadings prefix="nm"/>
</#if>

<#-- Add page break -->
<#if nmMessages?has_content && miscMessages?has_content>
    <div class="page-break"></div>
</#if>

<#-- Misc messages -->
<#if miscMessages?has_content>
    <table width="100%">
        <tr>
            <td class="table-header"><h4 id="misc">${text(''pdf.misc_nm'')}</h4></td>
        </tr>
    </table>
    <@renderMessageList messages=miscMessages areaHeadings=false/>
</#if>

</body>
</html>
', 'templates/messages/nm-report-pdf.ftl', 'FM');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (31, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '<#include "message-support.ftl"/>

<#--
    Split by ?filter rather than by appending to a list one message at a time.
    Appending builds a sequence out of a chain of concatenations, one link per
    message, and reading the n''th element walks the chain -- so printing the list
    afterwards costs the square of its length, which on a list of a whole year''s
    temporary and preliminary notices is most of the time to render it.
-->
<#assign tpMessages = messages?filter(msg ->
        msg.type == ''PRELIMINARY_NOTICE'' || msg.type == ''TEMPORARY_NOTICE'') />


<html>
<head>

    <meta http-equiv="Content-Type" content="text/html; charset=UTF-8"/>
    <title>${text("pdf.list.title")}</title>

    <@pageSizeStyle />
    <link rel="stylesheet" type="text/css" href="/css/templates/pdf.css">
    <link rel="stylesheet" type="text/css" href="/css/templates/common.css">

    <style type="text/css" media="all">
        td.table-item {
            vertical-align: top;
            width: 100%;
            padding: 5px 0;
        }
        .week-year-header {
            font-size: 24px;
            text-align: right;
            margin-top: 1cm;
            margin-bottom: 1mm;
        }
    </style>

</head>
<body>

<#-- ${weeks} is the issue''s weeks in the pair form the name patterns use: "36",
     "36+37" for a pair, "36-38" for three weeks or more, or the week label whole.
     The legacy print dialog hands only ${week}, which then prints alone. -->
<@renderDefaultHeaderAndFooter headerText="${text(''pdf.nm_tp'')} - ${text(''pdf.week'')} ${weeks!week!''''}, ${year!''''}"/>

<#-- First page -->
<h1>${text("pdf.nm_tp")}</h1>

<div class="week-year-header">
    ${text("pdf.week")} ${weeks!week!""}, ${year!""}
</div>

<table class="first-page-info-line" style="margin-bottom: 1cm">
    <tr>
        <td width="50%" align="left">
            ${.now?string(text("msg.time.date_format"))}
            <#if edition?? && edition != ''1''> - Version ${edition}</#if>
        </td>
        <td width="50%" align="right">
            ${text("pdf.nm_abbrev")}  ${weeks!week!""} ${year!""}
        </td>
    </tr>
</table>


<#-- T&P messages -->
<#if tpMessages?has_content>

    <#assign areaHeadingId=-9999999 />

     <table class="message-table">

         <#-- Define column widths (fixed table layout) -->
         <tr>
             <td style="width: 2.5cm"></td>
             <td style="width: 0.5cm"></td>
             <td width="*"></td>
         </tr>

        <#list tpMessages as msg>

            <#if msg.areas?has_content>
                <#assign area=areaHeading(msg.areas[0]) />
                <#if areaHeadings && area?? && area.id != areaHeadingId>
                    <#assign areaHeadingId=area.id />
                    <tr class="table-header-row">
                        <td colspan="3" class="table-item">
                            <h4 id="${areaHeadingId?c}"><@areaLineage area=areaHeading(area) /></h4>
                        </td>
                    </tr>
                </#if>
            <#elseif  areaHeadings && areaHeadingId == -9999999>
                <tr class="table-header-row">
                    <td colspan="3" class="table-header"><h4 id="${areaHeadingId?c}">${text("msg.area.general")}</h4></td>
                </tr>
                <#assign areaHeadingId=-9999998 />
            </#if>
            <tr>
                <td class="table-item">
                    <#if msg.shortId?has_content>
                        ${msg.shortId}
                    </#if>
                </td>
                <td class="table-item">
                    <#if msg.type == ''PRELIMINARY_NOTICE''>
                        (P)
                    <#elseif msg.type == ''TEMPORARY_NOTICE''>
                        (T)
                    </#if>
                </td>
                <td class="table-item">
                    <#if msg.descs?has_content && msg.descs[0].title?has_content>
                        ${msg.descs[0].title}
                    </#if>
                </td>
            </tr>
        </#list>
    </table>

</#if>


</body>
</html>
', 'templates/messages/nm-tp-report-pdf.ftl', 'FM');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (32, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '<#include "common.ftl"/>

<#macro aton defaultSubjectFields=true enDefaultName="" enDetails="" enNavtex="">

    <#if defaultSubjectFields>
        <@defaultSubjectFieldTemplates/>
    </#if>

    <field-template field="part.getDesc(''en'').details" format="html">
        <#list params.positions![] as pos>
            <@renderAtonType atonParams=pos defaultName="${enDefaultName}" format="long" lang="en"/>
            <@renderPositionList geomParam=pos lang="en"/> ${enDetails}.<br>
        </#list>
    </field-template>

    <#if promulgate(''navtex'')>
        <field-template field="message.promulgation(''navtex'').text" update="append">
            <#list params.positions![] as pos>
                <@line format="navtex">
                    <@renderAtonType atonParams=pos defaultName="${enDefaultName}" format="short" lang="en"/>
                    <@renderPositionList geomParam=pos format="navtex" lang="en"/> ${enNavtex}.
                </@line>
            </#list>
        </field-template>
    </#if>

    <#if promulgate(''safetynet'')>
        <field-template field="message.promulgation(''safetynet'').text" update="append">
            <#list params.positions![] as pos>
                <@line format="navtex">
                    <@renderAtonType atonParams=pos defaultName="${enDefaultName}" format="short" lang="en"/>
                    <@renderPositionList geomParam=pos format="navtex" lang="en"/> ${enNavtex}.
                </@line>
            </#list>
        </field-template>
    </#if>

</#macro>
', 'templates/tmpl/aton-common.ftl', 'FM');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (33, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '<#include "aton-common.ftl"/>


<#macro renderAtonReplacementType atonParams defaultName format=''long'' lang=''en''>
    <#if atonParams?has_content && atonParams.aton_replacement?has_content>
        <#assign desc=descForLang(atonParams.aton_replacement, lang)!>
        <#if desc?? && format == ''long''>
            ${desc.longValue}
        <#elseif desc??>
            ${desc.value}
        <#else>
            ${defaultName}
        </#if>
    <#else>
        ${defaultName}
    </#if>
</#macro>


<#macro atonReplaced enDefaultName="" enDefaultReplacementName="">

    <@defaultSubjectFieldTemplates/>

    <field-template field="part.getDesc(''en'').details" format="html">
        <#list params.positions![] as pos>
            <@renderAtonType atonParams=pos defaultName="${enDefaultName}" format="long" lang="en"/>
            <@renderPositionList geomParam=pos lang="en"/> has been replaced with
            <@renderAtonReplacementType atonParams=pos defaultName="${enDefaultReplacementName}" format="long" lang="en"/>
            <#if pos.aton_light?has_content>
                showing
                <@lightCharacterFormat light=pos.aton_light format="verbose" lang="en"/>
            </#if>.<br>
        </#list>
    </field-template>

    <#if promulgate(''navtex'')>
        <field-template field="message.promulgation(''navtex'').text" update="append">
            <#list params.positions![] as pos>
                <@line format="navtex">
                    <@renderAtonType atonParams=pos defaultName="${enDefaultName}" format="short" lang="en"/>
                    <@renderPositionList geomParam=pos format="navtex" lang="en"/> REPLACED WITH
                    <@renderAtonReplacementType atonParams=pos defaultName="${enDefaultReplacementName}" format="navtex" lang="en"/>
                    <#if pos.aton_light?has_content>
                        showing
                        <@lightCharacterFormat light=pos.aton_light format="normal" lang="en"/>
                    </#if>.
                </@line>
            </#list>
        </field-template>
    </#if>

    <#if promulgate(''safetynet'')>
        <field-template field="message.promulgation(''safetynet'').text" update="append">
            <#list params.positions![] as pos>
                <@line format="navtex">
                    <@renderAtonType atonParams=pos defaultName="${enDefaultName}" format="short" lang="en"/>
                    <@renderPositionList geomParam=pos format="navtex" lang="en"/> REPLACED WITH
                    <@renderAtonReplacementType atonParams=pos defaultName="${enDefaultReplacementName}" format="navtex" lang="en"/>
                    <#if pos.aton_light?has_content>
                        showing
                        <@lightCharacterFormat light=pos.aton_light format="normal" lang="en"/>
                    </#if>.
                </@line>
            </#list>
        </field-template>
    </#if>

</#macro>
', 'templates/tmpl/aton-replacement-common.ftl', 'FM');
