INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (49, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '<#include "common.ftl"/>

<#macro renderSubject value lang=''en''>
    <#if value?has_content>
        <#assign desc=descForLang(value, lang)!>
        <#if desc??>
            ${desc.value?cap_first}
        </#if>
    </#if>
</#macro>


<#if params.exercise_type??>
    <#list languages as lang>
        <field-template field="part.getDesc(''${lang}'').subject" format="text">
            <@renderSubject value=params.exercise_type lang=lang/>
        </field-template>
    </#list>
</#if>

<field-template field="part.getDesc(''en'').details" format="html">
    <#assign exerciseText=(params.exercise_type??)?then(getListValue(params.exercise_type, ''an exercise'', ''long'', ''en''), ''an exercise'')/>
