        ${exerciseText}
    <#else>
        ${exerciseText?cap_first}
    </#if>
    will take place
    <@renderPositionList geomParam=part lang="en"/>.
    Guard vessels will be in the area listening on VHF CH 16.
    Mariners are requested to pass with caution.
</field-template>

<#if promulgate(''navtex'')>
