INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (65, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '<#include "common.ftl"/>

<#assign areaLineage = ''org.niord.core.script.directive.AreaLineageDirective''?new()>


<#-- ***************************************  -->
<#-- Generates the NAVTEX header line         -->
<#-- ***************************************  -->
<#macro navtexHeader lang="en">
    <@areaLineage message=message lang=lang format="navtex"/>
</#macro>


<#-- ***************************************  -->
<#-- Generates the NAVTEX footer lines        -->
<#-- ***************************************  -->
<#macro navtexFooter>
    <#if message.references?has_content>
        <#list message.references as ref>
            <#if ref.type == ''CANCELLATION''>
                <@line format="navtex">
                    ${text(''cancellation.message'',ref.messageId)}.
                </@line>
            </#if>
        </#list>
    </#if>

    <#if message.publishDateTo?has_content>
        <@line format="navtex">
            <#assign cancelDate><@navtexDateFormat date=message.publishDateTo /></#assign>
            ${text(''cancellation.this_message'',cancelDate)}.
        </@line>
    </#if>
</#macro>


<#if promulgation.text?has_content>
    <#setting locale=''en''>
    <field-template field="promulgation.text">
<@navtexHeader/>

${promulgation.text}

<@navtexFooter/>
    </field-template>
</#if>
', 'templates/tmpl/navtex.ftl', 'FM');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (66, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '<#include "common.ftl"/>
<#include "markings.ftl"/>

<#macro renderObject defaultName format=''long'' lang=''en'' capFirst=false>
    <#assign result=defaultName!''''/>
    <#if params.object?has_content>
        <#assign desc=descForLang(params.object, lang)!>
        <#if desc?? && format == ''long''>
            <#assign result=desc.longValue/>
        <#elseif desc??>
            <#assign result=desc.value/>
        </#if>
    </#if>
    <#if capFirst>
        <#assign result=result?cap_first/>
    </#if>
    ${result}
</#macro>

<#-- The list values whose English name is plural; a deployment that adds its own adds their keys here -->
<#assign pluralObjects=[''object.adrift.logs'', ''object.adrift.fishing_stakes'']/>
<#assign objectVerb=(params.object?? && params.object.key?? && pluralObjects?seq_contains(params.object.key))?then(''have'', ''has'')/>


<#-- The subject is one line (TMPL15): renderObject prints its name on a line of its own, so it is captured and trimmed -->
<#assign objectName><@renderObject defaultName="Object" format="short" lang="en" capFirst=true/></#assign>
<field-template field="part.getDesc(''en'').subject" format="text">
    ${objectName?trim} adrift
</field-template>

<field-template field="part.getDesc(''en'').details" format="html">
    <@renderObject defaultName="an object" format="long" lang="en" capFirst=true/>
    ${objectVerb} been observed adrift <@renderPositionList geomParam=part lang="en"/>
    <#if params.date??><@renderDate date=params.date lang="en" tz="UTC"/></#if>.
    <#if params.cancelDate??>
        <p>Cancel this warning <@renderDate date=params.cancelDate lang="en" tz="UTC"/>.</p>
    </#if>
</field-template>

<#if promulgate(''navtex'')>
    <field-template field="message.promulgation(''navtex'').text" update="append">
        <@line format="navtex">
            <@renderObject defaultName="an object" format="short" lang="en" capFirst=true/>
            ADRIFT <@renderPositionList geomParam=part format="navtex" lang="en"/>
            <#if params.date??><@renderDate date=params.date lang="en" format="navtex"/></#if>.
        </@line>
    </field-template>
</#if>

<#if promulgate(''safetynet'')>
    <field-template field="message.promulgation(''safetynet'').text" update="append">
        <@line format="navtex">
            <@renderObject defaultName="an object" format="short" lang="en" capFirst=true/>
            ADRIFT <@renderPositionList geomParam=part format="navtex" lang="en"/>
            <#if params.date??><@renderDate date=params.date lang="en" format="navtex"/></#if>.
        </@line>
    </field-template>
</#if>
', 'templates/tmpl/object-adrift.ftl', 'FM');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (67, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '/*
 * Copyright 2017 Danish Maritime Authority.
 *
 * Licensed under the Apache License, Version 2.0 (the "License");
 * you may not use this file except in compliance with the License.
 * You may obtain a copy of the License at
 *
 *       http://www.apache.org/licenses/LICENSE-2.0
 *
 * Unless required by applicable law or agreed to in writing, software
 * distributed under the License is distributed on an "AS IS" BASIS,
 * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
 * See the License for the specific language governing permissions and
 * limitations under the License.
 */

// If an observation date is defined, define the publish date interval
// and event date interval based on the observation date
if (params.get(''date'') !== null) {
    var date = new java.util.Date(params.get(''date''));

    // Cancel message 12 hours after observation
    var offset = 12 * 60 * 60 * 1000;
    var cancelDate = new java.util.Date(params.get(''date'') + offset);
    params.put(''cancelDate'', cancelDate);

    // Update publication dates - assume manual publication, so, ignore start date
    //message.publishDateFrom = date;
    message.publishDateTo = cancelDate;

    // Update event dates
    var part = message.part(MessagePartType.DETAILS);
    if (part !== undefined) {
        var di = new org.niord.model.message.DateIntervalVo();
        di.allDay = false;
        di.fromDate = date;
        di.toDate = cancelDate;
        part.eventDates = new java.util.ArrayList();
        part.eventDates.add(di);
    }
}
', 'templates/tmpl/object-adrift.js', 'JS');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (68, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '<#include "common.ftl"/>

<#macro obstructionFound enDetails="" enNavtex="">

    <#assign enObj=enDetails?split("|")/>
    <#assign navtexObj=enNavtex?split("|")/>
    <#assign offset=multiplePositions(part)?then(2,0)/>
    <#assign verb=multiplePositions(part)?then(''have'', ''has'')/>

    <@defaultSubjectFieldTemplates/>

    <field-template field="part.getDesc(''en'').details" format="html">
        ${enObj[0+offset]?cap_first} ${verb} been reported
        <@renderPositionList geomParam=part lang="en" plural=true/>.
        ${enObj[1+offset]?cap_first} may be dangerous.<br>
        Mariners are advised to keep well clear.
    </field-template>

    <#if promulgate(''navtex'')>
        <field-template field="message.promulgation(''navtex'').text" update="append">
            <@line format="navtex">
                ${navtexObj[0+offset]} REPORTED FOUND
                <@renderPositionList geomParam=part lang="en" format="navtex" plural=true/>.
                ${navtexObj[1+offset]} MAY BE DANGEROUS.
            </@line>
            <@line format="navtex">
                MARINERS ADVISED TO KEEP CLEAR.
            </@line>
        </field-template>
    </#if>

    <#if promulgate(''safetynet'')>
        <field-template field="message.promulgation(''safetynet'').text" update="append">
            <@line format="navtex">
                ${navtexObj[0+offset]} REPORTED FOUND
                <@renderPositionList geomParam=part lang="en" format="navtex" plural=true/>.
                ${navtexObj[1+offset]} MAY BE DANGEROUS.
            </@line>
            <@line format="navtex">
                MARINERS ADVISED TO KEEP CLEAR.
            </@line>
        </field-template>
    </#if>

</#macro>
', 'templates/tmpl/obstruction-found.ftl', 'FM');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (69, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '<#include "common.ftl"/>
