            <@renderPositionList geomParam=part format="navtex" lang="en"/>
            <#if params.locality?has_content>IN ENTRANCE TO ${params.locality}</#if>.
        </@line>
        <@line format="navtex">
            MARINERS ADVISED TO KEEP CLEAR.
        </@line>
    </field-template>
</#if>
', 'templates/tmpl/reduced-depth.ftl', 'FM');
