            </#if>
        </@line>
        <@line format="navtex">
            <@renderMarkings markings=params.markings! markingType=params.markingType! lang="en" format="navtex"  unmarkedText="UNMARKED"/>
        </@line>
        <@line format="navtex">
            MARINERS ADVISED TO KEEP CLEAR.
        </@line>
    </field-template>
</#if>
', 'templates/tmpl/uncharted-obstruction.ftl', 'FM');
