INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (79, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '
<#-- ***************************************  -->
<#-- Renders information about a work vessel  -->
<#-- ***************************************  -->

<#macro renderWorkVessel vessel lang="en" format="details">
    <#setting locale=lang>

    <#if vessel?has_content && (vessel.name?has_content || vessel.callSign?has_content)>

        <#assign csFormat=(format == ''audio'')?then(''verbose'',''normal'')/>

        <#if lang == "en">

            <#if vessel.name?has_content>
                <#if format == ''navtex''>
                    By <@quote text=vessel.name/>
                <#elseif format == ''audio''>
                    Work is carried out by <@quote text=vessel.name/>
                <#else>
                    Work is carried out by <@quote text=vessel.name format="angular"/>
                </#if>
            <#elseif format == ''navtex''>
                By vessel with
            <#else>
                Work is carried out by the vessel with
            </#if>
            <#if vessel.callSign?has_content>call sign <@callSignFormat callSign=vessel.callSign format=csFormat/></#if>.
            <#if vessel.guardVessels!false>
                <#if format == ''navtex''>
                    Guard vessels in area.
                <#else>
                    Guard vessels will be in the area.
                </#if>
            </#if>
            <#if vessel.contact!false>
                <#if format == ''navtex''>
                    Listening VHF CH 16
                    <#if vessel.channel?has_content>and ${vessel.channel}</#if>.
                <#else>
                    The <#if vessel.guardVessels!false>vessels are<#else>vessel is</#if>
                    listening on VHF channel 16
                    <#if vessel.channel?has_content>and ${vessel.channel}</#if>.
                </#if>
            </#if>
        </#if>
    </#if>

    <#-- The minimum distance without a grouping comma, which in NAVTEX reads as a decimal sign ("1,000M"); a text as
         it was typed (?c would quote it) (TMPL14) -->
    <#if vessel?has_content && vessel.minDist?has_content>
        <#local minDist=vessel.minDist?is_number?then(vessel.minDist?c, vessel.minDist?string)/>
    </#if>
    <#if format == ''navtex''>
        MARINERS REQUESTED TO PASS WITH CAUTION
        <#if vessel.minDist?has_content>
            KEEPING MINIMUM DISTANCE ${minDist}${(vessel.minDistType!''m'')?upper_case}
        </#if>.
    <#else>
        Mariners are requested to pass with caution
        <#if vessel.minDist?has_content>
            and keep a minimum distance of ${minDist}${(vessel.minDistType!''m'')}
        </#if>.
    </#if>
</#macro>
', 'templates/tmpl/work-vessel.ftl', 'FM');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (80, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '<#include "common.ftl"/>
<#include "markings.ftl"/>

<#-- A number prints without a grouping comma, which in NAVTEX reads as a decimal sign ("1,250M"); a text as it was
     typed (?c would quote it) (TMPL14) -->
<#function plainNumber value>
    <#return value?is_number?then(value?c, value?string)/>
</#function>

<#macro renderVesselType defaultName format=''long'' lang=''en''>
    <#if params.wreck_type?has_content>
        <#assign desc=descForLang(params.wreck_type, lang)!>
        <#if desc?? && format == ''long''>
            ${desc.longValue?cap_first}
        <#elseif desc??>
            ${desc.value?cap_first}
        <#else>
            ${defaultName?cap_first}
        </#if>
    <#else>
        ${defaultName?cap_first}
    </#if>
</#macro>

<field-template field="part.getDesc(''en'').subject" format="text">
    <#switch params.markingType!''''>
        <#case ''marking''>Marked Wreck<#break>
        <#case ''buoy''>Buoyed Wreck<#break>
        <#default>Unmarked Wreck
    </#switch>
</field-template>

<field-template field="part.getDesc(''en'').details" format="html">
    <@renderVesselType defaultName="a vessel" format="long" lang="en"/>
    has sunk <@renderPositionList geomParam=part lang="en"/>.
    <#if params.wreck_visible!false>
        The wreck is visible above the sea surface.
    <#else>
        The depth above the wreck is <#if params.wreck_depth??>${plainNumber(params.wreck_depth)}m.<#else>unknown.</#if>
    </#if>
    The wreck is <@renderMarkings markings=params.markings! markingType=params.markingType! lang="en" format="details" unmarkedText="unmarked"/><br>
    Mariners are advised to keep well clear.
</field-template>

<#if promulgate(''navtex'')>
    <field-template field="message.promulgation(''navtex'').text" update="append">
        <@line format="navtex">
            <@renderVesselType defaultName="A VESSEL" format="short" lang="en"/>
            SUNK <@renderPositionList geomParam=part format="navtex" lang="en"/>.
            <#if params.wreck_visible!false>
                WRECK VISIBLE ABOVE SEA SURFACE.
            <#else>
                DEPTH ABOVE WRECK <#if params.wreck_depth??>${plainNumber(params.wreck_depth)}M.<#else>UNKNOWN.</#if>
            </#if>
            WRECK <@renderMarkings markings=params.markings! markingType=params.markingType! lang="en" format="navtex"  unmarkedText="UNMARKED"/>
        </@line>
        <@line format="navtex">
            MARINERS ADVISED TO KEEP CLEAR.
        </@line>
    </field-template>
</#if>

<#if promulgate(''safetynet'')>
    <field-template field="message.promulgation(''safetynet'').text" update="append">
        <@line format="navtex">
            <@renderVesselType defaultName="A VESSEL" format="short" lang="en"/>
            SUNK <@renderPositionList geomParam=part format="navtex" lang="en"/>.
            <#if params.wreck_visible!false>
                WRECK VISIBLE ABOVE SEA SURFACE.
            <#else>
                DEPTH ABOVE WRECK <#if params.wreck_depth??>${plainNumber(params.wreck_depth)}M.<#else>UNKNOWN.</#if>
            </#if>
            WRECK <@renderMarkings markings=params.markings! markingType=params.markingType! lang="en" format="navtex"  unmarkedText="UNMARKED"/>
        </@line>
        <@line format="navtex">
            MARINERS ADVISED TO KEEP CLEAR.
        </@line>
    </field-template>
</#if>
', 'templates/tmpl/wreck.ftl', 'FM');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (1000001, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '
<#include "../messages/message-support.ftl"/>

<#setting time_zone="Europe/Copenhagen">

<html>
<head>
    <link rel="stylesheet" type="text/css" href="/css/templates/mail.css">
</head>
<body>

<h1>
    Danske farvandsefterretninger ${.now?string["EEEEEEE ''den'' d. MMMMMMMMM yyyy"]}
</h1>

<h2>
    Her er Forsvarets Operationscenter med dagens farvandsefterretninger
</h2>

<#list messages as msg>
    <#assign audio=promulgation(msg, ''audio'')!>
    <#if audio?? && audio.text?has_content>
    <p>
        <#if msg.areas?has_content>
            <u>
                <@areaLineage area=msg.areas[0] />
                <#assign msgDesc=descForLang(msg, language)!>
                <#if msgDesc?? && msgDesc.vicinity?has_content>
                    - ${msgDesc.vicinity}
                </#if>
            </u>
            <br>
        </#if>
        <@txtToHtml text=audio.text/>
    </p>
    </#if>
</#list>

<#if params[''firingExercises'']?? && params[''firingExercisesDate'']??>
<h2>
    Der afholdes i morgen
    ${params[''firingExercisesDate'']?string["EEEEEEE ''den'' d. MMMMMMMMM yyyy"]}
    følgende skydeøvelser:
</h2>

    <#list params[''firingExercises''] as fe>
    <p>
        Ved <@areaLineage area=fe.area />
        <#list fe.times as t>
            <#if !t?is_first>og igen</#if>
            fra kl ${t.fromDate?string["HHmm"]}
            til kl ${t.toDate?string["HHmm"]}<#if t?is_last>.</#if>
        </#list>
    </p>
    </#list>
</#if>

<p>
    Det var farvandsefterretningerne.
</p>

</body>
</html>
', 'templates/mailinglist/audio-broadcast.ftl', 'FM');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (1000002, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '/*
 * Copyright 2017 Danish Maritime Authority.
 *
