 * you may not use this file except in compliance with the License.
 * You may obtain a copy of the License at
 *
 *       http://www.apache.org/licenses/LICENSE-2.0
 *
 * Unless required by applicable law or agreed to in writing, software
 * distributed under the License is distributed on an "AS IS" BASIS,
 * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
 * See the License for the specific language governing permissions and
 * limitations under the License.
 */



var messageService = CdiUtils.getBean(org.niord.core.message.MessageSearchService.class);

var date = java.util.Calendar.getInstance();
date.add(java.util.Calendar.DAY_OF_YEAR, 1);
params.put(''firingExercisesDate'', date.getTime());

var timeZone = java.util.TimeZone.getTimeZone(''Europe/Copenhagen'');
var fromDate = org.niord.core.util.TimeUtils.resetTime(date.getTime(), timeZone);
var toDate = org.niord.core.util.TimeUtils.endOfDay(date.getTime(), timeZone);

var seriesIds = java.util.Collections.singleton(''dma-fe'');
var statuses = java.util.Collections.singleton(org.niord.model.message.Status.PUBLISHED);
var searchParams = new org.niord.core.message.MessageSearchParams();
searchParams.seriesIds(seriesIds)
    .statuses(statuses)
    .dateType(org.niord.core.message.MessageSearchParams$DateType.EVENT_DATE)
    .from(fromDate)
    .to(toDate);

// searchOrFail, not search: a failed search fails the trigger, which the scheduler postpones, where search would
// answer it with an empty list and the mail would tell its readers that there are no firing exercises tomorrow
var searchResult = messageService.searchOrFail(searchParams);

var areaFilter = org.niord.model.DataFilter.get().fields(''DETAILS'').lang(language);

var result = new java.util.ArrayList();
for (var x = 0; x < searchResult.size; x++) {
    var fe = searchResult.data[x];
    var data = new java.util.HashMap();
    if (fe.areas === undefined || fe.areas.length === 0) {
        continue;
    }
    data.put(''area'', fe.areas[0].toVo(org.niord.model.message.AreaVo.class, areaFilter));

    var times = new java.util.ArrayList();
    for (var p = 0; p < fe.parts.length; p++) {
        var part = fe.parts[p];
        if (part.eventDates && part.eventDates.length > 0) {
            for (var d = 0; d < part.eventDates.length; d++) {
                var evtDate = part.eventDates[d];
                if (evtDate.fromDate !== undefined && evtDate.toDate !== undefined &&
                    evtDate.fromDate.before(toDate) &&
                    evtDate.toDate.after(fromDate)) {
                    times.add(evtDate.toVo());
                }
            }
        }
    }
    if (times.isEmpty()) {
        continue;
    }

    data.put(''times'', times);
    result.add(data);
}

params.put("firingExercises", result);

', 'templates/mailinglist/fetch-firing-exercises.js', 'JS');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (1000003, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '<#include "common.ftl"/>

<#macro renderStatus format=''long'' lang=''en''>
    <#if params.dgps_status?has_content>
        <#assign desc=descForLang(params.dgps_status, lang)!>
        <#if desc?? && format == ''long''>
        ${desc.longValue}
        <#elseif desc??>
        ${desc.value}
        </#if>
    </#if>
</#macro>

<#macro renderStationName format=''long'' lang=''en''>
    <#if params.dgps_station?has_content>
        <#assign desc=descForLang(params.dgps_station, lang)!>
        <#if desc??>
        ${desc.value}
        </#if>
    </#if>
</#macro>

<#if params.dgps_station?? && params.dgps_station.key??>
    <#assign key=params.dgps_station.key>

<#if languages?seq_contains(''da'')>
<field-template field="part.getDesc(''da'').subject" format="text">
    DGPS <@renderStatus format="normal" lang="da"/>
</field-template>
</#if>

<field-template field="part.getDesc(''en'').subject" format="text">
    DGPS <@renderStatus format="normal" lang="en"/>
</field-template>

<#if languages?seq_contains(''da'')>
<field-template field="part.getDesc(''da'').details" format="html">
    <#setting locale=''da''>
    <@renderStationName format="long" lang="da"/> DGPS-station
    på pos. <@formatPos lat=params.station.coordinates[1] lon=params.station.coordinates[0] format=''dec-1'' />
    og frekvens ${params.station.frequency?string["0.0"]} kHz
    <@renderStatus format="long" lang="da"/>
    <#if part.eventDates?has_content && part.eventDates[0].fromDate??>
        <@renderDateIntervals dateIntervals=part.eventDates lang="da"/>
    </#if>.
</field-template>
</#if>

<field-template field="part.getDesc(''en'').details" format="html">
    <#setting locale=''en''>
    <@renderStationName format="long" lang="en"/> DGPS-station
    in pos. <@formatPos lat=params.station.coordinates[1] lon=params.station.coordinates[0] format=''dec-1'' />
    and frequency ${params.station.frequency?string["0.0"]} kHz
    <@renderStatus format="long" lang="en"/>
    <#if part.eventDates?has_content && part.eventDates[0].fromDate??>
        <@renderDateIntervals dateIntervals=part.eventDates lang="en" tz="UTC"/>
    </#if>.
</field-template>

<#if promulgate(''audio'')>
    <field-template field="message.promulgation(''audio'').text" update="append">
        <#setting locale=''da''>
        <@line>
            <@renderStationName format="long" lang="da"/> DGPS-station
            på pos. <@formatPos lat=params.station.coordinates[1] lon=params.station.coordinates[0] format=''audio'' />
            og frekvens ${params.station.frequency?string["0.0"]} kHz
            <@renderStatus format="long" lang="da"/>
            <#if part.eventDates?has_content && part.eventDates[0].fromDate??>
                <@renderDateIntervals dateIntervals=part.eventDates format="plain" lang="da"/>
            </#if>.
        </@line>
    </field-template>
</#if>

<#if promulgate(''navtex'')>
    <field-template field="message.promulgation(''navtex'').text" update="append">
        <#setting locale=''en''>
        <@line format="navtex">
            DGPS-station <@renderStationName format="long" lang="en"/>
            ${params.station.frequency?string["0.0"]} kHz
            <@formatPos lat=params.station.coordinates[1] lon=params.station.coordinates[0] format=''navtex'' />
            <@renderStatus format="normal" lang="en"/>
            <#if part.eventDates?has_content && part.eventDates[0].fromDate??>
                <@renderDateIntervals dateIntervals=part.eventDates format="navtex" lang="en"/>
            </#if>.
        </@line>
    </field-template>
</#if>

</#if>
', 'templates/tmpl/dgps.ftl', 'FM');
INSERT INTO public."ScriptResource" (id, created, updated, version, content, path, type) VALUES (1000004, '2026-10-22 00:00:00', '2026-10-22 00:00:00', 0, '
/*
 * Copyright 2017 Danish Maritime Authority.
 *
 * Licensed under the Apache License, Version 2.0 (the "License");
 * you may not use this file except in compliance with the License.
 * You may obtain a copy of the License at
 *
 *       http://www.apache.org/licenses/LICENSE-2.0
 *
 * Unless required by applicable law or agreed to in writing, software
 * distributed under the License is distributed on an "AS IS" BASIS,
 * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
 * See the License for the specific language governing permissions and
 * limitations under the License.
 */

load(''niord:templates/tmpl/common.js'');

message.areas.clear();
var areaService = CdiUtils.getBean(org.niord.core.area.AreaService.class);
var dk = areaService.findByName(''Danmark'', ''da'', null);
if (dk) {
    var dkVo = dk.toVo(
        org.niord.model.message.AreaVo.class,
        org.niord.model.DataFilter.get());
    message.areas.add(dkVo);
}

var dgpsStation = {
    ''radio_navigation.dgps.skagen'' :  {
        frequency: 296.0,
        coordinates: Java.to([ 10.59512710571289, 57.74877166748047],"double[]"),
        transmitters: [ ''Baltico'', ''Rogaland'' ]
    },
    ''radio_navigation.dgps.blåvand'' :  {
        frequency: 290.0,
        coordinates: Java.to([ 8.08320140838623, 55.5578498840332],"double[]"),
        transmitters: [ ''Baltico'', ''Rogaland'' ]
    },
    ''radio_navigation.dgps.hammer_odde'' :  {
        frequency: 289.5,
        coordinates: Java.to([ 14.773825645446777, 55.298221588134766],"double[]"),
        transmitters: [ ''Baltico'' ]
    },
    ''radio_navigation.dgps.torshavn'' :  {
        frequency: 287.5,
        coordinates: Java.to([ -6.837833404541016, 62.02050018310547],"double[]"),
        transmitters: [ ''Rogaland'' ]
    }
};

// Update the geometry of the message part
if (params.dgps_station
    && params.dgps_station.key) {
    var station = dgpsStation[params.dgps_station.key];
    if (station !== undefined) {
        part.geometry.features.length = 0;

        var feature = new org.niord.model.geojson.FeatureVo();
        var pt = new org.niord.model.geojson.PointVo();
        pt.coordinates = station.coordinates;
        feature.geometry = pt;
        part.geometry.features = Java.to([ feature ], "org.niord.model.geojson.FeatureVo[]");

        var navtex = message.promulgation(''navtex'');
        if (navtex !== null) {
            navtex.promulgate = true;
            for (var t = 0; t < station.transmitters.length; t++) {
                var transmitter = station.transmitters[t];
                if (navtex.transmitters !== undefined && navtex.transmitters.containsKey(transmitter)) {
                    navtex.transmitters.put(transmitter, true);
                }
            }
        }

        params.put(''station'', station);
    }
}
', 'templates/tmpl/dgps.js', 'JS');


